syntax:
struct StructName {
    // Members with default access 'public' if no access specifier is specified
    MemberType memberName; // implicitly public in struct
};

code_example:
#include <iostream>

struct S {
    int a; // 'a' is public by default in struct
};

int main() {
    S s;
    s.a = 10; // Accessing public member directly
    std::cout << "s.a = " << s.a << std::endl;
    return 0;
}
